  order_id STRING OPTIONS(description="Pancake order identifier."),
  system_id INT64 OPTIONS(description="Pancake system id. Whole-number strings are cast safely; invalid/fractional values become NULL."),
  status STRING OPTIONS(description="Pancake status; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  status_name STRING OPTIONS(description="Pancake status_name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
