  total_price FLOAT64 OPTIONS(description="Total price as FLOAT64 from the supplied core DDL, in source currency."),
  shipping_fee FLOAT64 OPTIONS(description="Shipping fee as FLOAT64 from the supplied core DDL, in source currency."),
  surcharge_amount FLOAT64 OPTIONS(description="Surcharge amount as FLOAT64 from the supplied core DDL, in source currency."),
