  transfer_amount FLOAT64 OPTIONS(description="Transfer amount as FLOAT64 from the supplied core DDL, in source currency."),
  paid_cash FLOAT64 OPTIONS(description="Paid cash as FLOAT64 from the supplied core DDL, in source currency."),
  charged_by_card FLOAT64 OPTIONS(description="Charged by card as FLOAT64 from the supplied core DDL, in source currency."),
  charged_by_momo FLOAT64 OPTIONS(description="Charged by momo as FLOAT64 from the supplied core DDL, in source currency."),
  charged_by_qrpay FLOAT64 OPTIONS(description="Charged by qrpay as FLOAT64 from the supplied core DDL, in source currency."),
  bank_payments FLOAT64 OPTIONS(description="Bank payments as FLOAT64 from the supplied core DDL, in source currency."),
  tax_amount FLOAT64 OPTIONS(description="Tax amount as FLOAT64 from the supplied core DDL, in source currency."),
  partner_fee FLOAT64 OPTIONS(description="Partner fee as FLOAT64 from the supplied core DDL, in source currency."),
  buyer_total_amount FLOAT64 OPTIONS(description="Buyer total amount as FLOAT64 from the supplied core DDL, in source currency."),
  advanced_platform_fee_marketplace_voucher FLOAT64 OPTIONS(description="Advanced platform fee marketplace voucher as FLOAT64 from the supplied core DDL, in source currency."),
  total_marketplace_fee FLOAT64 OPTIONS(description="Total marketplace fee as FLOAT64 from the supplied core DDL, in source currency."),
  total_price_after_sub_discount FLOAT64 OPTIONS(description="Total price after sub discount as FLOAT64 from the supplied core DDL, in source currency."),
  exchange_payment_paid FLOAT64 OPTIONS(description="Exchange payment paid as FLOAT64 from the supplied core DDL, in source currency."),
  cod FLOAT64 OPTIONS(description="Cod as FLOAT64 from the supplied core DDL, in source currency."),
  cod_money_to_collect FLOAT64 OPTIONS(description="Cod money to collect as FLOAT64 from the supplied core DDL, in source currency."),
  return_reason_code INT64 OPTIONS(description="Pancake return reason code. Whole-number strings are cast safely; invalid/fractional values become NULL."),
  return_reason STRING OPTIONS(description="Pancake returned_reason_name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  exchange_value FLOAT64 OPTIONS(description="Exchange value as FLOAT64 from the supplied core DDL, in source currency."),
  shipping_address_commune_name STRING OPTIONS(description="Pancake shipping_address.commune_name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  shipping_address_province_name STRING OPTIONS(description="Pancake shipping_address.province_name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
