  warehouse_name STRING OPTIONS(description="Pancake warehouse_info.name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  marketplace_id INT64 OPTIONS(description="Pancake marketplace id. Whole-number strings are cast safely; invalid/fractional values become NULL."),
  notes STRING OPTIONS(description="Pancake note; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  print_notes STRING OPTIONS(description="Pancake note_print; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  tags STRING OPTIONS(description="Pancake tags; kept as text. May be Python-serialized nested data; retained as text, not assumed to be JSON. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  customer_currency STRING OPTIONS(description="Pancake customer.currency; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  customer_id STRING OPTIONS(description="Pancake customer.customer_id; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  customer_succeed_order_count INT64 OPTIONS(description="Pancake customer succeed order count. Whole-number strings are cast safely; invalid/fractional values become NULL."),
  customer_inserted_at STRING OPTIONS(description="Pancake customer inserted_at value retained as STRING to match the core DDL; the loader formats source timestamps in Asia/Ho_Chi_Minh local time."),
  is_block_customer FLOAT64 OPTIONS(description="Pancake customer block flag stored as FLOAT64 to match the supplied core DDL."),
  customer_updated_at STRING OPTIONS(description="Pancake customer updated_at value retained as STRING to match the core DDL; the loader formats source timestamps in Asia/Ho_Chi_Minh local time."),
  customer_order_count INT64 OPTIONS(description="Pancake customer order count. Whole-number strings are cast safely; invalid/fractional values become NULL."),
  customer_returned_order_count INT64 OPTIONS(description="Pancake customer returned order count. Whole-number strings are cast safely; invalid/fractional values become NULL."),
  customer_purchased_amount FLOAT64 OPTIONS(description="Customer purchased amount as FLOAT64 from the supplied core DDL, in source currency."),
  customer_last_order_at STRING OPTIONS(description="Pancake customer last_order_at value retained as STRING to match the core DDL; the loader formats source timestamps in Asia/Ho_Chi_Minh local time."),
