  advanced_platform_fee_diff_shipping_fee FLOAT64 OPTIONS(description="Advanced platform fee diff shipping fee as FLOAT64 from the supplied core DDL, in source currency."),
  advanced_platform_fee_payment_fee FLOAT64 OPTIONS(description="Advanced platform fee payment fee as FLOAT64 from the supplied core DDL, in source currency."),
  advanced_platform_fee_seller_transaction_fee FLOAT64 OPTIONS(description="Advanced platform fee seller transaction fee as FLOAT64 from the supplied core DDL, in source currency."),
  advanced_platform_fee_service_fee FLOAT64 OPTIONS(description="Advanced platform fee service fee as FLOAT64 from the supplied core DDL, in source currency."),
  assigning_care_name STRING OPTIONS(description="Pancake assigning_care.name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  assigning_care_email STRING OPTIONS(description="Pancake assigning_care.email; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  time_assigned_care STRING OPTIONS(description="Pancake time_assign_care value retained as STRING to match the core DDL; the loader formats source timestamps in Asia/Ho_Chi_Minh local time."),
  last_editor_name STRING OPTIONS(description="Pancake last_editor.name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  last_editor_email STRING OPTIONS(description="Pancake last_editor.email; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  creator_name STRING OPTIONS(description="Pancake creator.name; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved."),
  creator_email STRING OPTIONS(description="Pancake creator.email; kept as text. Surrounding whitespace is trimmed and blank values become NULL; case is preserved.")
)
PARTITION BY DATE(inserted_at)
CLUSTER BY order_id, warehouse_id, order_sources_code
OPTIONS(
  description="One row per Pancake order in the rolling 30 complete business-date window. Replaces the full inserted_at partition window on every run."
);
